    const yuan = buZhouLuJing(base, String(a.from ?? a.source ?? a.src ?? a.path ?? ''));
    const ming2 = buZhouLuJing(base, String(a.to ?? a.destination ?? a.dest ?? a.targetPath ?? ''));
