  board = new KanbanCang(path.join(userData, 'board'));
  knowledge = new ZhishiCang(path.join(userData, 'knowledge'));
  duBanDaiHui();
  checkpoints = new JianChaDianCang(path.join(userData, 'checkpoints'));
  // 第 67 轮 项 13：工具写盘前留原件（工作区外也能回档）
