/**
 * **内置插件播种（第 42 轮，T5）**：把随包的 `plugins/mcp-bridge` 复制进默认插件目录，
 * 并在 `chaJianJi` 里登记一条 **enabled:false** 的记录 —— 用户要求"插件里看得到、但默认不启动"。
 * 为什么不靠扫描自动发现：扫描会把发现到的插件标成 `enabled: true`（真机行为），
 * 那样一开箱就是启用的，与产品口径相反。
 */
function boZhongNeiZhiChaJian(): void {
  try {
    const ming = 'mcp-bridge';
    /** 开发态 app.getAppPath() 可能是仓库根，也可能是包目录 —— 两处都试，别猜一个 */
    const gen = app.getAppPath();
    const houXuan = [
      path.join(gen, 'plugins', ming),
      path.join(gen, 'packages', 'app-shell', 'plugins', ming),
      path.join(process.cwd(), 'plugins', ming),
      path.join(process.cwd(), 'packages', 'app-shell', 'plugins', ming),
    ];
    const src = houXuan.find((x) => fs.existsSync(path.join(x, 'bridge.mjs')));
    if (!src) return;
    const mu = path.join(app.getPath('userData'), 'scan-dirs', 'plugins');
    const dst = path.join(mu, ming);
    try { fs.mkdirSync(mu, { recursive: true }); } catch { /* 已存在 */ }
    if (!fs.existsSync(dst)) {
      try { fs.cpSync(src, dst, { recursive: true }); } catch { /* 复制失败不挡启动 */ }
    }
    const s = settingsStore?.load() as { chaJianJi?: Array<Record<string, unknown>> } | undefined;
    const arr = Array.isArray(s?.chaJianJi) ? s.chaJianJi.slice() : [];
    const id = 'warmy-plugin-mcp-bridge';
    if (!arr.some((x) => String((x || {}).id || '') === id)) {
      arr.push({ id, ming: 'MCP 桥接（mcp-bridge）', desc: '把 MCP 服务器桥接成牛马可用的工具；默认不启动。', path: dst, enabled: false });
      try { settingsStore?.save({ chaJianJi: arr } as never); } catch { /* noop */ }
      try { audit?.log('plugin.seed-mcp-bridge', { dst }); } catch { /* noop */ }
    }
  } catch { /* 播种失败不影响启动 */ }
}
chuliIpc('warmy:chaJianJiSaoMiao', () => {
  try {
    const dirs = chaRuMoRenMuLu([], 'plugins');
    try {
      const s = (settingsStore?.load?.() || {}) as { pluginScanDirs?: string[] };
      const extra = Array.isArray(s.pluginScanDirs) ? s.pluginScanDirs.map(String) : [];
      for (const d of extra) if (!dirs.includes(d)) dirs.push(d);
    } catch { /* noop */ }
    const found: Array<{ id: string; path: string; ming: string; desc: string }> = [];
    const skipped: Array<{ dir: string; reason: string }> = [];
    for (const dir of dirs.slice(0, 10)) {
      try {
        if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) {
          skipped.push({ dir, reason: 'not-a-directory' });
          continue;
        }
        for (const ming of fs.readdirSync(dir)) {
          const p = path.join(dir, ming);
          try {
            if (!fs.statSync(p).isDirectory()) continue;
            const pkg = path.join(p, 'package.json');
            const jineng = path.join(p, 'SKILL.md');
            if (!fs.existsSync(pkg) && !fs.existsSync(jineng)) continue;
            let xiangmuMing = ming;
            let xiangmuShuoming = '';
            if (fs.existsSync(pkg)) {
              try {
                const j = JSON.parse(fs.readFileSync(pkg, 'utf8'));
                xiangmuMing = String(j.name || ming);
                xiangmuShuoming = String(j.description || '');
              } catch { /* keep folder ming */ }
            }
            if (found.some((f) => f.id === xiangmuMing)) continue;
            found.push({ id: xiangmuMing, path: p, ming: xiangmuMing, desc: xiangmuShuoming });
          } catch { /* skip entry */ }
        }
      } catch (e) {
        skipped.push({ dir, reason: xiJingCuoWu(e) });
      }
    }
    audit?.log('chaJianJi.scan', { dirs: dirs.length, found: found.length });
    return { ok: true, found, skipped, scannedDirs: dirs };
  } catch (e) {
    return { ok: false, error: xiJingCuoWu(e) };
  }
});

/**
 * dsh-market 市场资料（设置 → 技能 的「打开 dsh-market」弹窗用）。
 *
 * **只给能核实的东西**：仓库元信息（api.github.com）+ README 里的官方安装命令原文。
 * 它 4200+ 插件的目录由站点运行时提供，仓库里没有可读的目录接口 ⇒
 * **这里绝不编一份假列表**；抓不到就 `ok:false` 带原因，界面如实显示"没拿到，可在浏览器看"。
 */
chuliIpc('warmy:dshShiChangZiLiao', async () => {
  const CANKAO = {
    repo: 'dsh-market/dsh-market',
    readme: 'https://raw.githubusercontent.com/dsh-market/dsh-market/main/README.md',
    api: 'https://api.github.com/repos/dsh-market/dsh-market',
  };
  const qu = async (u: string) => {
    const r = await fetch(u, { headers: { 'user-agent': 'WArmy-desktop', accept: 'application/vnd.github+json' }, signal: AbortSignal.timeout(9000) });
    return { ok: r.ok, text: await r.text() };
  };
  try {
    const [j, rd] = await Promise.all([qu(CANKAO.api).catch(() => null), qu(CANKAO.readme).catch(() => null)]);
    let xin: Record<string, unknown> = {};
    try { xin = j?.ok ? JSON.parse(j.text) as Record<string, unknown> : {}; } catch { xin = {}; }
    const wen = String(rd?.text || '');
    /** README 里的安装命令**原样**抠出来，不自己编 */
    const mingLing = [...new Set((wen.match(/^dsh\s+plugin[^\n`]*$/gm) || []).map((x) => x.trim()))].slice(0, 4);
    if (!Object.keys(xin).length && !wen) {
      return { ok: false, error: 'market-unreachable', repo: CANKAO.repo, url: `https://github.com/${CANKAO.repo}` };
    }
    return {
      ok: true,
      repo: CANKAO.repo,
      url: `https://github.com/${CANKAO.repo}`,
      homepage: String(xin.homepage || ''),
      description: String(xin.description || ''),
      stars: Number(xin.stargazers_count || 0),
      forks: Number(xin.forks_count || 0),
      openIssues: Number(xin.open_issues_count || 0),
      license: String((xin.license as { spdx_id?: string } | undefined)?.spdx_id || ''),
      pushedAt: String(xin.pushed_at || ''),
      installCommands: mingLing.length ? mingLing : ['dsh plugin --profile web add dshmarket'],
      readmeChars: wen.length,
      catalog: null as null | Array<{ ming: string; miaoShu: string; xing: string }>,
      catalogNote: '插件目录由 dsh-market 站点运行时提供，仓库未公开可读目录接口 ⇒ 这里不列插件（不编造）。',
    };
  } catch (e) {
    return { ok: false, error: xiJingCuoWu(e).slice(0, 120), repo: CANKAO.repo, url: `https://github.com/${CANKAO.repo}` };
  }
});

