/** 图片附件预览：小图给 data URL（读不了/不是图片如实返回 ok:false） */
chuliIpc('warmy:wenJianYuLan', (_e, p0?: { path?: string; maxBytes?: number }) => {
  try {
    const p = String(p0?.path || '').trim();
    if (!p || !fs.existsSync(p)) return { ok: false, error: 'not-found' };
    const cap = Math.max(1024, Math.min(Number(p0?.maxBytes) || 3 * 1024 * 1024, 8 * 1024 * 1024));
    const st = fs.statSync(p);
    if (st.size > cap) return { ok: false, error: 'too-large' };
    const mime = /\.png$/i.test(p) ? 'image/png'
      : /\.jpe?g$/i.test(p) ? 'image/jpeg'
      : /\.gif$/i.test(p) ? 'image/gif'
      : /\.webp$/i.test(p) ? 'image/webp'
      : /\.bmp$/i.test(p) ? 'image/bmp'
      : /\.svg$/i.test(p) ? 'image/svg+xml'
      : '';
    if (!mime) return { ok: false, error: 'not-image' };
    return { ok: true, dataUrl: `data:${mime};base64,${fs.readFileSync(p).toString('base64')}`, bytes: st.size };
  } catch (e) { return { ok: false, error: xiJingCuoWu(e) }; }
});
/**
 * **任意文件的字节数**：附件条要显示"多大"（产品要求：图片/文档/压缩包都要显示，
 * 且超过 1024 要逐级进位到 KB/MB/GB —— 进位在渲染层做，这里只给真实字节数）。
 */
chuliIpc('warmy:wenJianDaXiao', (_e, p0?: { path?: string }) => {
  try {
    const p = String(p0?.path || '').trim();
    if (!p || !fs.existsSync(p)) return { ok: false, error: 'not-found' };
    const st = fs.statSync(p);
    if (!st.isFile()) return { ok: false, error: 'not-a-file' };
    return { ok: true, bytes: st.size };
  } catch (e) { return { ok: false, error: xiJingCuoWu(e) }; }
});
/**
 * 第 35 轮 项 11：**批量问"这些路径真的存在吗"**。
 *
 * 聊天里凡是长得像路径的字符串都会被渲染成超链接；但模型经常写出
 * `C:\Users\你\Desktop\xxx.txt` 这种**占位/虚拟路径**（或者只是文档里的举例），
 * 对它弹"复制/复制路径/打开目录"菜单是错的 —— 用户点了只会报错。
 * 所以渲染完成后向主进程核一遍真实存在性，**只有存在的才挂右键菜单**。
 */
chuliIpc('warmy:luJingCunZai', (_e, p0?: { paths?: string[] }) => {
  try {
    const lie = Array.isArray(p0?.paths) ? p0.paths.slice(0, 200) : [];
    const jie: Record<string, boolean> = {};
    for (const x of lie) {
      const p = String(x || '').trim();
      if (!p) continue;
      try { jie[p] = fs.existsSync(p); } catch { jie[p] = false; }
    }
    return { ok: true, cunZai: jie };
  } catch (e) { return { ok: false, error: xiJingCuoWu(e), cunZai: {} }; }
});
/**
 * 第 35 轮 项 12：**点开行动明细里的路径 = 打开编辑，不是运行**。
 *
 * 产品原话："鼠标点击可以直接打开（不能运行，如果是命令类的就打开编辑，而不是运行，
 * 如果是无法打开编辑的文件就显示不能编辑的提示）"。
 * `shell.openPath()` 对 `.exe/.bat/.ps1` 是**执行**，所以这里先拦掉可执行文件，
 * 只把"人类可编辑"的交给系统默认程序；其余如实返回 `cannot-edit` 由界面提示。
 */
const BU_KE_BIAN_JI = /\.(exe|com|msi|msix|bat|cmd|ps1|psm1|vbs|vbe|js|jse|wsf|wsh|scr|pif|cpl|jar|appx|dll|sys|lnk)$/i;
chuliIpc('warmy:daKaiBianJi', async (_e, p0?: { path?: string }) => {
  try {
    const p = String(p0?.path || '').trim();
    if (!p || !fs.existsSync(p)) return { ok: false, error: 'not-found' };
    if (BU_KE_BIAN_JI.test(p)) return { ok: false, error: 'cannot-edit' };
    const cuo = await shell.openPath(p);
    if (cuo) return { ok: false, error: cuo };
    return { ok: true, path: p };
  } catch (e) { return { ok: false, error: xiJingCuoWu(e) }; }
});
/** 在资源管理器里显示这个文件（导出后给用户看文件在哪） */
chuliIpc('warmy:xianShiWenJianJia', (_e, p0?: { path?: string }) => {  try {
    const p = String(p0?.path || '').trim();
    if (!p || !fs.existsSync(p)) return { ok: false, error: 'not-found' };
    shell.showItemInFolder(p);
    return { ok: true, path: p };
  } catch (e) { return { ok: false, error: xiJingCuoWu(e) }; }
});

// ── R. 启动引导 ──
chuliIpc('warmy:chuShiSheZhiTai', () => {
  try {
    const s = settingsStore?.load() as Record<string, unknown> | undefined;
    // 首次运行/安装后首启：setupDone 非 true 一律弹语言选择
    const done = (s as { setupDone?: boolean })?.setupDone === true;
    const guideDone = (s as { guideDone?: boolean })?.guideDone === true;
    /**
     * 第一句对话是否发生过：落盘标记优先；老用户没有标记时看会话日志里有没有 user 消息
     * （日志在启动时已从记忆 JSONL 重建）。这里只读内存，不额外扫盘。
     */
    const guideChatDone = (s as { guideChatDone?: boolean })?.guideChatDone === true
      || [...chatLogs.values()].some((arr) => (arr || []).some((e) => guiYiJiaoSe(e.role) === 'user'));
    let privacyRevoked = false;
    try { privacyRevoked = fs.existsSync(path.join(app.getPath('userData'), 'auth', 'privacy-revoked')); } catch { /* noop */ }
    return { ok: true, done, guideDone, guideChatDone, privacyRevoked, yuYan: s?.yuYan || app.getLocale() };
  } catch (e) { return { ok: false, error: xiJingCuoWu(e) }; }
});
chuliIpc('warmy:chuShiSheZhiWanCheng', (_e, payload: { yuYan?: string; provider?: Record<string, unknown>; guideDone?: boolean; guideChatDone?: boolean }) => {
  try {
    if (payload.yuYan) settingsStore?.save({ yuYan: payload.yuYan } as never);
    /** 首启选了语言：默认层与默认称呼当场跟着换（第 54 轮项 1） */
    if (payload.yuYan) {
      try { moRenYuYanTongBu(); } catch { /* 不许影响首启 */ }
      try { yongHuMingSuiYuYan(); } catch { /* noop */ }
    }
    if (payload.guideDone) settingsStore?.save({ guideDone: true } as never);
    /** 第一句对话成功：只写 true，永不回写 false（避免一次失败把已完成状态抹掉） */
    if (payload.guideChatDone) settingsStore?.save({ guideChatDone: true } as never);
    if (payload.provider) {
      // 预填 provider
      Object.assign(providerCfg, {
        presetId: (payload.provider.presetId as string) || providerCfg.presetId,
        apiKey: (payload.provider.apiKey as string) || providerCfg.apiKey,
        baseURL: (payload.provider.baseURL as string) || providerCfg.baseURL,
        model: (payload.provider.model as string) || providerCfg.model,
      });
    }
    const cur = settingsStore?.load() as unknown as Record<string, unknown>;
    settingsStore?.save({ ...cur, setupDone: true } as never);
    return { ok: true };
  } catch (e) { return { ok: false, error: xiJingCuoWu(e) }; }
});

/** Skill enable/pause flags (default enabled when key missing) */
function jinengQiyongYingShe(): Record<string, boolean> {
  try {
    const s = settingsStore?.load() as { skillEnabled?: Record<string, boolean> } | undefined;
    return (s && s.skillEnabled && typeof s.skillEnabled === 'object') ? { ...s.skillEnabled } : {};
  } catch {
    return {};
  }
}
chuliIpc('warmy:jinengJiSheZhiEnabled', (_e, payload: { id?: string; enabled?: boolean }) => {
  try {
    const id = String(payload?.id || '');
    if (!id) return { ok: false, error: 'missing-id' };
    const map = jinengQiyongYingShe();
    map[id] = payload?.enabled !== false;
    settingsStore?.save({ skillEnabled: map } as never);
    return { ok: true, id, enabled: map[id] };
  } catch (e) {
    return { ok: false, error: xiJingCuoWu(e) };
  }
});
